// Repro: the radar feed and the locked card sit side by side on /ops/radar.
// Assumes the feed and the locked card are reachable by role name, and the
// layout symptom is checked on the feed's container via computed style.
await page.goto('/ops/radar');

const feed = page.getByRole('region', { name: 'Radar feed' });
const locked = page.getByRole('region', { name: 'Locked card' });

await expect(feed).toBeVisible();
await expect(locked).toBeVisible();

// Symptom: the two blocks are laid out in a row, so they should not share
// the same flex row. The feed's parent should be a column layout.
await expect(feed.locator('xpath=..')).toHaveCSS('flex-direction', 'column');
